/bin/bash -lc "/work1/zixuan/envs/conda_envs/causalmemagent/bin/python -c 'import math; from scipy.stats import beta; delta=.05/8; print(\"delta\",delta,\"n_zero\",math.ceil(math.log(delta)/math.log(.9)));
for n in [49,60,80,100,120,160,200]:
 max_bad=max([k for k in range(n+1) if (1 if k==n else beta.ppf(1-delta,k+1,n-k))<=.10],default=-1)
 min_good=min([k for k in range(n+1) if (0 if k==0 else beta.ppf(delta,k,n-k+1))>=.50],default=None)
 print(n,\"A01 max accepts\",max_bad,\"A11 min retained\",min_good,\"rate\",None if min_good is None else min_good/n,\"zeroU\",1-delta**(1/n))'
for p in [.6,.65,.7,.75,.8]:
 good=[]
 for n in range(1,501):
  k=math.floor(p*n)
  if k and beta.ppf(delta,k,n-k+1)>=.5: good.append((n,k,k/n)); break
 print(\"observed target\",p,\"first\",good[:1])'"

